void Solver::rephase() {
    // 1. reset the rephase counter
    rephases = 0;

    // 2. make the next rephase a bit harder to trigger:
    //    shrink the threshold only 5% (instead of 10%) so we keep a larger
    //    window before the next restart‑triggered rephase.
    threshold = static_cast<int>(threshold * 0.95);

    // 3. adaptively enlarge the limit – the more conflicts we have seen,
    //    the larger the step, but always add a base of 4096.
    rephase_limit += 4096 + (conflicts / 1000);

    // 4. decide which phase to save for the next search.
    //    If recent learnt clauses have high LBD (i.e., the search is hard),
    //    flip the saved phase; otherwise keep the best local phase.
    int max_lbd = 0;
    for (int i = 0; i < 50; ++i) {
        if (lbd_queue[i] > max_lbd) max_lbd = lbd_queue[i];
    }

    if (max_lbd > 30) {                     // hard region → invert phase
        for (int v = 1; v <= vars; ++v) saved[v] = -local_best[v];
    } else {                                // easy region → keep best phase
        for (int v = 1; v <= vars; ++v) saved[v] = local_best[v];
    }

    // 5. occasional random perturbation (10 % chance) to escape stagnation
    if (rand() % 100 < 10) {
        for (int v = 1; v <= vars; ++v)
            saved[v] = (rand() & 1) ? 1 : -1;
    }
}
